//! Exact self-addressing-identifier fixtures generated by the pinned TypeScript reference.

use std::error::Error;

use keri_cesr::crypto::digest::DigestAlgorithm;
use keri_protocol::said::{DUMMY_CHARACTER, Said, SaidError, SaidVerification};
use keri_protocol::serialization::{Sad, SadValue};
use serde::Deserialize;

const REFERENCE_SHA: &str = "91a04a5edd804425f42be75ffbf034f8d14e5cb2";

#[derive(Debug, Deserialize)]
struct Fixture {
    schema_version: u8,
    upstream: String,
    reference_sha: String,
    generated_on: String,
    sources: Vec<String>,
    dummy_character: String,
    default_label: String,
    cases: Vec<SaidCase>,
    verification: Verification,
    rejected_cases: Vec<RejectedCase>,
    reference_quirks: ReferenceQuirks,
}

#[derive(Debug, Deserialize)]
struct SaidCase {
    name: String,
    label: String,
    input_sad_json: String,
    placeholder: String,
    placeholder_width: usize,
    preimage: String,
    preimage_hex: String,
    preimage_byte_size: usize,
    said: String,
    said_code: String,
    completed_sad_json: String,
    completed_version_string: Option<String>,
}

#[derive(Debug, Deserialize)]
#[expect(
    clippy::struct_excessive_bools,
    reason = "each field mirrors one recorded reference verify() outcome; grouping them into enums \
              would obscure the one-to-one correspondence with the fixture"
)]
struct Verification {
    completed_default: bool,
    completed_prefixed: bool,
    completed_prefixed_versioned: bool,
    tampered_content_default: bool,
    restamped_version_prefixed_versioned: bool,
}

#[derive(Debug, Deserialize)]
struct RejectedCase {
    name: String,
    reference_error_category: String,
    reference_error_message: String,
    rust_error_category: String,
}

#[derive(Debug, Deserialize)]
struct ReferenceQuirks {
    default_verify_ignores_the_identifier_field: IgnoredFieldQuirk,
    derive_appends_a_missing_label: AppendQuirk,
    constructor_super_called_twice: RejectedCase,
}

#[derive(Debug, Deserialize)]
struct IgnoredFieldQuirk {
    empty_identifier_accepted: bool,
    unrelated_identifier_accepted: bool,
    unrelated_identifier_rejected_when_prefixed: bool,
    note: String,
    rust_decision: String,
    rust_error_category: String,
}

#[derive(Debug, Deserialize)]
struct AppendQuirk {
    input_sad_json: String,
    reference_result_json: String,
    note: String,
    rust_error_category: String,
}

fn fixture() -> Result<Fixture, Box<dyn Error>> {
    Ok(serde_json::from_str(include_str!(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/fixtures/said/v1.json"
    )))?)
}

fn decode_hex(input: &str) -> Result<Vec<u8>, Box<dyn Error>> {
    if !input.len().is_multiple_of(2) {
        return Err("odd-length hexadecimal fixture field".into());
    }
    (0..input.len())
        .step_by(2)
        .map(|index| {
            input
                .get(index..index + 2)
                .ok_or_else(|| Box::<dyn Error>::from("hexadecimal fixture slice out of range"))
                .and_then(|pair| u8::from_str_radix(pair, 16).map_err(Into::into))
        })
        .collect()
}

/// Rebuilds `sad` with one field's value replaced, preserving the original field order.
///
/// The crate keeps in-place replacement internal, so tests reconstruct through the public
/// insertion API rather than widening that surface.
fn with_field(sad: &Sad, label: &str, value: &SadValue) -> Result<Sad, Box<dyn Error>> {
    let mut rebuilt = Sad::new();
    for (existing, existing_value) in sad.entries() {
        if existing == label {
            rebuilt.insert(existing.to_owned(), value.clone())?;
        } else {
            rebuilt.insert(existing.to_owned(), existing_value.clone())?;
        }
    }
    Ok(rebuilt)
}

fn said_error_category(error: &SaidError) -> &'static str {
    match error {
        SaidError::MissingLabelField { .. } => "MissingLabelField",
        SaidError::VariableWidthAlgorithm { .. } => "VariableWidthAlgorithm",
        SaidError::DigestMismatch => "DigestMismatch",
        SaidError::LabelFieldMismatch => "LabelFieldMismatch",
        SaidError::VersionStringMismatch => "VersionStringMismatch",
        SaidError::Sad { .. } => "Sad",
        SaidError::Serialization { .. } => "Serialization",
        SaidError::Crypto { .. } => "Crypto",
        _ => "Unknown",
    }
}

#[test]
fn fixture_metadata_matches_the_pinned_reference() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.schema_version, 1);
    assert_eq!(fixture.upstream, "https://github.com/WebOfTrust/signify-ts.git");
    assert_eq!(fixture.reference_sha, REFERENCE_SHA);
    assert_ne!(fixture.generated_on, "");
    assert_eq!(fixture.sources, ["src/keri/core/saider.ts", "test/core/saider.test.ts"]);
    assert_eq!(fixture.dummy_character, DUMMY_CHARACTER.to_string());
    assert_eq!(fixture.default_label, keri_protocol::said::DEFAULT_SAID_LABEL);
    Ok(())
}

#[test]
fn every_reference_identifier_derives_exactly() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.cases.len(), 3);

    for case in &fixture.cases {
        assert_eq!(case.said_code, "E", "case {}", case.name);

        // The placeholder is exactly as wide as the identifier that replaces it, which is what
        // keeps the version-string size correct for the finished message.
        assert_eq!(case.placeholder_width, case.said.len(), "case {}", case.name);
        assert!(
            case.placeholder.chars().all(|character| character == DUMMY_CHARACTER),
            "case {} placeholder is not all dummy characters",
            case.name
        );

        let expected_preimage = decode_hex(&case.preimage_hex)?;
        assert_eq!(
            expected_preimage,
            case.preimage.as_bytes(),
            "case {} preimage hex/text disagree",
            case.name
        );
        assert_eq!(expected_preimage.len(), case.preimage_byte_size, "case {}", case.name);

        let sad = Sad::from_json_bytes(case.input_sad_json.as_bytes())?;
        let computed = Said::compute(&sad, DigestAlgorithm::Blake3_256, &case.label)?;

        assert_eq!(computed.said().qb64()?, case.said, "case {}", case.name);
        assert_eq!(computed.said().code().as_str(), case.said_code, "case {}", case.name);

        // The completed data must match the reference byte for byte, including field order.
        let expected_completed = Sad::from_json_bytes(case.completed_sad_json.as_bytes())?;
        assert_eq!(computed.sad(), &expected_completed, "case {}", case.name);
        assert_eq!(
            computed.sad().get_text("v").map(str::to_owned),
            case.completed_version_string,
            "case {}",
            case.name
        );

        // Verifying the reference's own completed data must succeed under the strict policy.
        let reference_said = Said::from_qb64(&case.said)?;
        reference_said.verify(&expected_completed, &case.label, SaidVerification::strict())?;
    }
    Ok(())
}

#[test]
fn the_hashed_preimage_matches_byte_for_byte() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    for case in &fixture.cases {
        // Rebuild the placeholder-bearing intermediate exactly as derivation does, then confirm it
        // equals the bytes the reference hashed. This isolates the placeholder-and-size step from
        // the digest itself, so a mismatch points at serialization rather than at BLAKE3.
        let sad = Sad::from_json_bytes(case.input_sad_json.as_bytes())?;
        let placeholder: String = core::iter::repeat_n(DUMMY_CHARACTER, case.placeholder_width).collect();
        let dummied = with_field(&sad, &case.label, &SadValue::text(placeholder))?;

        let preimage = if dummied.contains("v") {
            keri_protocol::serialization::SerializedEvent::from_sad(dummied)?
                .raw()
                .to_vec()
        } else {
            dummied.to_json_bytes()?
        };
        assert_eq!(preimage, case.preimage.as_bytes(), "case {}", case.name);
    }
    Ok(())
}

#[test]
fn reference_verification_outcomes_are_reproduced() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let case = fixture.cases.first().ok_or("fixture has no cases")?;
    let completed = Sad::from_json_bytes(case.completed_sad_json.as_bytes())?;
    let said = Said::from_qb64(&case.said)?;

    // Everything the reference accepts on the completed message, Rust accepts too.
    assert!(fixture.verification.completed_default);
    assert!(fixture.verification.completed_prefixed);
    assert!(fixture.verification.completed_prefixed_versioned);
    said.verify(&completed, &case.label, SaidVerification::digest_only())?;
    said.verify(&completed, &case.label, SaidVerification::label_only())?;
    said.verify(&completed, &case.label, SaidVerification::strict())?;

    // Everything the reference rejects, Rust rejects with a typed reason.
    assert!(!fixture.verification.tampered_content_default);
    let tampered = with_field(&completed, "r", &SadValue::text("logs/tampered"))?;
    assert!(matches!(
        said.verify(&tampered, &case.label, SaidVerification::digest_only()),
        Err(SaidError::DigestMismatch)
    ));

    assert!(!fixture.verification.restamped_version_prefixed_versioned);
    let restamped = with_field(&completed, "v", &SadValue::text("KERI10JSON000000_"))?;
    assert!(matches!(
        said.verify(&restamped, &case.label, SaidVerification::strict()),
        Err(SaidError::VersionStringMismatch)
    ));
    Ok(())
}

#[test]
fn reference_rejections_map_to_stable_rust_error_categories() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    for case in &fixture.rejected_cases {
        assert_ne!(case.reference_error_category, "");
        assert_ne!(case.reference_error_message, "");
        match case.name.as_str() {
            "saidify_missing_label" => {
                assert_eq!(case.rust_error_category, "MissingLabelField");
                let sad = Sad::from_json_bytes(br#"{"v":"KERI10JSON000000_","t":"rep"}"#)?;
                let error = Said::compute(&sad, DigestAlgorithm::Blake3_256, "d")
                    .err()
                    .ok_or("expected a missing-label rejection")?;
                assert_eq!(said_error_category(&error), case.rust_error_category);
            }
            "unsupported_digest_code" => {
                assert_eq!(case.rust_error_category, "UnrepresentableInRust");
                // `DigestAlgorithm` names only the algorithm the pinned reference implements, so
                // an unsupported digest code cannot be requested at all.
                assert!(case.reference_error_message.contains("Unsupported digest code"));
            }
            other => return Err(format!("unmapped rejected case {other}").into()),
        }
    }
    Ok(())
}

#[test]
fn reference_quirks_are_pinned_and_safely_diverged() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let quirks = &fixture.reference_quirks;
    let case = fixture.cases.first().ok_or("fixture has no cases")?;
    let said = Said::from_qb64(&case.said)?;
    let original = Sad::from_json_bytes(case.input_sad_json.as_bytes())?;

    // 1. The reference's default verify never inspects the identifier field, so it accepts a
    //    message whose `d` is empty or unrelated. Rust requires a match unless asked otherwise.
    let ignored = &quirks.default_verify_ignores_the_identifier_field;
    assert!(ignored.empty_identifier_accepted);
    assert!(ignored.unrelated_identifier_accepted);
    assert!(!ignored.unrelated_identifier_rejected_when_prefixed);
    assert_ne!(ignored.note, "");
    assert_ne!(ignored.rust_decision, "");
    assert_eq!(ignored.rust_error_category, "LabelFieldMismatch");

    let error = said
        .verify(&original, &case.label, SaidVerification::strict())
        .err()
        .ok_or("strict verification accepted an empty identifier field")?;
    assert_eq!(said_error_category(&error), ignored.rust_error_category);
    // The permissive policy exists, is explicitly named, and reproduces the reference outcome.
    said.verify(&original, &case.label, SaidVerification::digest_only())?;

    let unrelated = with_field(
        &original,
        "d",
        &SadValue::text("EBabiu_JCkE0GbiglDXNB5C4NQq-hiGgxhHKXBxkiojg"),
    )?;
    assert!(matches!(
        said.verify(&unrelated, &case.label, SaidVerification::strict()),
        Err(SaidError::LabelFieldMismatch)
    ));
    said.verify(&unrelated, &case.label, SaidVerification::digest_only())?;

    // 2. The reference's public derive appends an absent label at the end of the field order.
    let append = &quirks.derive_appends_a_missing_label;
    assert_ne!(append.note, "");
    assert!(append.reference_result_json.contains(r#""d":"#));
    assert!(
        !append.input_sad_json.contains(r#""d":"#),
        "the input must not already carry the label"
    );
    let without_label = Sad::from_json_bytes(append.input_sad_json.as_bytes())?;
    let error = Said::compute(&without_label, DigestAlgorithm::Blake3_256, "d")
        .err()
        .ok_or("expected a missing-label rejection")?;
    assert_eq!(said_error_category(&error), append.rust_error_category);

    // 3. The reference constructor calls super() twice when the identifier field is populated, so
    //    the natural "check a received message" path throws instead of verifying.
    let constructor = &quirks.constructor_super_called_twice;
    assert_eq!(constructor.reference_error_category, "ReferenceError");
    assert!(constructor.reference_error_message.contains("Super constructor"));
    assert_eq!(constructor.rust_error_category, "UnreachableInRust");
    // Rust reaches the same goal without a constructor overload: parse the claimed identifier and
    // verify against it.
    let completed = Sad::from_json_bytes(case.completed_sad_json.as_bytes())?;
    let claimed = completed
        .get_text(&case.label)
        .ok_or("completed data lacks its identifier field")?;
    Said::from_qb64(claimed)?.verify(&completed, &case.label, SaidVerification::strict())?;
    Ok(())
}
